import Foundation

// Container Orchestration Rate Limiter with Retry Logic
// Manages container deployment scheduling across cluster nodes

struct DeploymentRequest {
    let containerID: String
    let nodeID: Int
    let priority: Int32
    let retryCount: Int32
    let baseDelayMs: Int32
}

class RateLimitBucket {
    private var tokens: Int32
    private let maxTokens: Int32
    private let refillRate: Int32
    private var lastRefillTime: UInt64

    init(maxTokens: Int32, refillRate: Int32) {
        self.maxTokens = maxTokens
        self.tokens = maxTokens
        self.refillRate = refillRate
        self.lastRefillTime = DispatchTime.now().uptimeNanoseconds
    }

    func tryConsume(count: Int32) -> Bool {
        refill()
        guard tokens >= count else { return false }
        tokens -= count
        return true
    }

    private func refill() {
        let now = DispatchTime.now().uptimeNanoseconds
        let elapsed = now - lastRefillTime
        let newTokens = Int32(elapsed / 1_000_000_000) * refillRate
        tokens = min(tokens + newTokens, maxTokens)
        lastRefillTime = now
    }
}

class RetryScheduler {
    private let maxRetries: Int32 = 5
    private let maxDelayMs: Int32 = 30000

    /// Computes exponential backoff delay with jitter
    /// Uses priority-weighted delay calculation
    func computeDelay(for request: DeploymentRequest) -> Int32 {
        guard request.retryCount <= maxRetries else {
            return -1 // Signal: no more retries
        }

        // Priority-weighted exponential backoff
        // Higher priority (lower number) = shorter delay
        let priorityFactor = computePriorityFactor(priority: request.priority)
        let exponentialDelay = computeExponentialComponent(
            baseDelay: request.baseDelayMs,
            retryCount: request.retryCount
        )

        // Combine: delay = exponentialDelay * priorityFactor / 100
        let weightedDelay = applyPriorityWeight(
            delay: exponentialDelay,
            factor: priorityFactor
        )

        return min(weightedDelay, maxDelayMs)
    }

    /// Priority factor: maps priority 0-10 to percentage 10-200
    private func computePriorityFactor(priority: Int32) -> Int32 {
        let clampedPriority = max(0, min(priority, 10))
        // Linear mapping: priority 0 -> 10%, priority 10 -> 200%
        return 10 + (clampedPriority * 19)
    }

    /// Exponential component: baseDelay * 2^retryCount
    /// Uses bit shifting for efficiency
    private func computeExponentialComponent(baseDelay: Int32, retryCount: Int32) -> Int32 {
        // Shift left by retryCount to compute 2^retryCount multiplier
        let shift = min(retryCount, 30) // Cap shift to prevent UB
        let multiplier = Int32(1) << shift

        // Multiply base delay by the exponential multiplier
        // This intermediate result feeds into priority weighting
        let result = baseDelay * multiplier
        return result
    }

    /// Apply priority weight: delay * factor / 100
    private func applyPriorityWeight(delay: Int32, factor: Int32) -> Int32 {
        // Use widening multiplication to avoid overflow in intermediate
        let wide = Int64(delay) * Int64(factor)
        let scaled = wide / 100

        // Narrow back to Int32 for the scheduling system
        if scaled > Int64(Int32.max) {
            return Int32.max
        }
        if scaled < Int64(Int32.min) {
            return Int32.min
        }
        return Int32(scaled)
    }
}

class ContainerOrchestrator {
    private let rateLimiter: RateLimitBucket
    private let scheduler: RetryScheduler
    private var pendingDeployments: [DeploymentRequest] = []
    private var deploymentDelays: [String: Int32] = [:]

    init(tokensPerSecond: Int32 = 100) {
        self.rateLimiter = RateLimitBucket(maxTokens: tokensPerSecond, refillRate: tokensPerSecond)
        self.scheduler = RetryScheduler()
    }

    func scheduleDeployment(_ request: DeploymentRequest) -> (allowed: Bool, delayMs: Int32) {
        // Check rate limit first
        let tokenCost = computeTokenCost(for: request)

        if rateLimiter.tryConsume(count: tokenCost) {
            return (true, 0)
        }

        // Rate limited - compute retry delay
        let delay = scheduler.computeDelay(for: request)
        if delay < 0 {
            return (false, -1) // Exhausted retries
        }

        deploymentDelays[request.containerID] = delay
        return (false, delay)
    }

    /// Token cost scales with retry count to prevent retry storms
    private func computeTokenCost(for request: DeploymentRequest) -> Int32 {
        let baseCost: Int32 = 1
        let retryCostMultiplier = request.retryCount + 1
        return baseCost * retryCostMultiplier
    }
}

// Entry point for testing
func processDeploymentBatch(requests: [DeploymentRequest]) -> [(String, Bool, Int32)] {
    let orchestrator = ContainerOrchestrator(tokensPerSecond: 50)
    var results: [(String, Bool, Int32)] = []

    for request in requests {
        let (allowed, delay) = orchestrator.scheduleDeployment(request)
        results.append((request.containerID, allowed, delay))
    }

    return results
}
